/**
 * Remove an NFS share. It touches no shared folder and no file. When no other share uses the folder's bind mount, OMV removes that mount's entry too. Computers lose access once the pending changes are applied; it marks the nfs and avahi modules dirty. Its reply is an empty list.
 * @summary Stop letting a computer use a shared folder over NFS
 */
export const nfsDeleteShare = (
  objectUuidRequest: BodyType<ObjectUuidRequest>,
  options?: SecondParameter<typeof rpcClient>,
  signal?: AbortSignal,
) => {
  return rpcClient<NfsShareRemoved>(
    {
      url: `/rpc/NFS/deleteShare`,
      method: "POST",
      headers: { "Content-Type": "application/json" },
      data: objectUuidRequest,
      signal,
    },
    options,
  );
};

